node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {parse} from '@babel/parser';
const sha=b=>createHash('sha256').update(b).digest('hex');
const old=JSON.parse(readFileSync('projects/ai-proxy/.opendesk-preview/source-68e774ea-ebdd-48e3-acfc-7a7de011267f/manifest.json'));
const stripped=new Set(['start','end','loc','extra','comments','leadingComments','trailingComments','innerComments']);
const normal=n=>Array.isArray(n)?n.map(normal):n&&typeof n==='object'?Object.fromEntries(Object.entries(n).filter(([k])=>!stripped.has(k)).map(([k,v])=>[k,normal(v)])):n;
function walk(n,fn){if(!n||typeof n!=='object')return;fn(n);for(const [k,v]of Object.entries(n)){if(stripped.has(k))continue;if(Array.isArray(v))v.forEach(x=>walk(x,fn));else if(v&&typeof v==='object')walk(v,fn);}}
const files=['projects/ai-proxy/src/Settings.tsx','projects/ai-proxy/src/ui/useProxy.ts','projects/ai-proxy/tests/settings-rules-runtime.test.mjs','projects/ai-proxy/tests/use-proxy-errors.test.mjs'];
const results=files.map(file=>{
 const current=readFileSync(file,'utf8'),base=execFileSync('git',['show','HEAD:'+file],{encoding:'utf8'});
 const baselineMatchesPriorCandidate=!old.sources[file]||old.sources[file].sha256===sha(base);
 if(!baselineMatchesPriorCandidate)throw Error('HEAD baseline does not match previous candidate: '+file);
 const parseText=s=>parse(s,{sourceType:'module',plugins:['jsx','typescript']});
 const getPatterns=tree=>{const out=[];walk(tree,n=>{
  if(n.type==='CallExpression'&&n.callee?.object?.name==='console'&&n.callee?.property?.name==='log')out.push({kind:'console.log',line:n.loc.start.line});
  if(n.type==='CatchClause'&&!n.body.body.length)out.push({kind:'empty-catch',line:n.loc.start.line});
  if(n.type==='JSXAttribute'&&n.name?.name==='dangerouslySetInnerHTML')out.push({kind:'raw-html',line:n.loc.start.line});
  if(n.type==='VariableDeclarator'&&/^(api_?key|secret|access_?token|password)$/i.test(n.id?.name??'')&&n.init?.type==='StringLiteral'&&n.init.value)out.push({kind:'hardcoded-secret-candidate',line:n.loc.start.line});
 });return out;};
 const currentAst=parseText(current),baseAst=parseText(base);
 const functions=tree=>{const m=new Map();walk(tree,n=>{if(n.type==='FunctionDeclaration'&&n.id&&n.id.name!=='App')m.set(n.id.name,JSON.stringify(normal(n)));});return m;};
 const now=functions(currentAst),was=functions(baseAst);
 return {file,sha256:sha(current),baselineSha256:sha(base),baselineMatchesPriorCandidate,parse:'PASS',changedNamedFunctions:[...new Set([...now.keys(),...was.keys()])].filter(k=>now.get(k)!==was.get(k)),baselinePatterns:getPatterns(baseAst),currentPatterns:getPatterns(currentAst)};
});
const catalogs=['en','zh-CN','zh-TW'].map(locale=>({locale,data:JSON.parse(readFileSync('projects/ai-proxy/src/i18n/locales/'+locale+'.json','utf8'))}));
const keyString=JSON.stringify(Object.keys(catalogs[0].data).sort());
const relevant=['editNamedRule','deleteNamedRule','confirmDeleteRule','apRuleExactScope','apRuleSubdomainScope','apRuleAlreadyExists','apRuleSavedNotice'];
const locales=catalogs.map(({locale,data})=>{
 if(JSON.stringify(Object.keys(data).sort())!==keyString)throw Error('Locale key mismatch');
 for(const key of ['editNamedRule','deleteNamedRule','confirmDeleteRule'])if(!data[key].includes('{domain}')||!data[key].includes('{scope}'))throw Error('Missing scope/domain: '+locale+key);
 return {locale,count:Object.keys(data).length,strings:Object.fromEntries(relevant.map(k=>[k,data[k]]))};
});
console.log(JSON.stringify({status:'PASS',kind:'Babel AST and JSON checks, not semantic typecheck',files:results,locales},null,2));
