realEntryCompile.command:
node --input-type=module <<'JS'
import {build} from 'esbuild';
import {resolve,relative} from 'node:path';
import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const captured=new Map();
const result=await build({
  absWorkingDir:process.cwd(),entryPoints:['projects/ai-proxy/src/main.jsx'],
  bundle:true,write:false,platform:'browser',format:'iife',target:'es2022',jsx:'automatic',
  alias:{'@opendesk/ui':resolve('src/ui/react/components/ui/button.tsx')},
  loader:{'.dat':'text'},define:{'process.env.NODE_ENV':JSON.stringify('production')},
  outdir:'__memory_only_ai_proxy_review__',metafile:true,
  plugins:[{name:'read-only-input-binding',setup(b){
    b.onLoad({filter:/\.(?:[cm]?[jt]sx?|css|json|dat)$/},args=>{
      const contents=readFileSync(args.path);captured.set(args.path,hash(contents));
      let ext=args.path.split('.').at(-1);
      const loader=ext==='dat'?'text':ext==='mjs'||ext==='cjs'?'js':ext;
      return {contents,loader};
    });
  }}]
});
const inputs=Object.keys(result.metafile.inputs).map(path=>{const filePath=path.split('?')[0];return {path:filePath,metafilePath:path,sha256:captured.get(resolve(filePath))??hash(readFileSync(filePath))};});
const drift=inputs.filter(item=>hash(readFileSync(item.path))!==item.sha256).map(item=>item.path);
const outputs=result.outputFiles.map(file=>({path:relative(process.cwd(),file.path),bytes:file.contents.length,sha256:hash(file.contents)}));
if(drift.length||!outputs.some(f=>f.path.endsWith('.js'))||!outputs.some(f=>f.path.endsWith('.css')))throw Error('Invalid build proof '+JSON.stringify({drift,outputs}));
console.log(JSON.stringify({status:'PASS',esbuildWrite:false,format:'iife',loader:{'.dat':'text'},alias:{'@opendesk/ui':'src/ui/react/components/ui/button.tsx'},warnings:result.warnings,outputs,inputCount:inputs.length,inputs,drift},null,2));
